"""Save PC byte evidence and the bounded death/respawn transition contract."""
import importlib.util,hashlib,json,re,struct
from pathlib import Path
spec=importlib.util.spec_from_file_location('n',Path(__file__).with_name('native-x86.py'));native=importlib.util.module_from_spec(spec);spec.loader.exec_module(native)
from capstone import Cs,CS_ARCH_X86,CS_MODE_32
n=native.NativeX86();BASE=native.BASE;dis=Cs(CS_ARCH_X86,CS_MODE_32)
functions={0x49c080:'TakeHitCode',0x41b420:'ResetPlayer',0x41af70:'ResetPlayerMoves',0x62f150:'AnimPlaying',0x62e040:'AnimDuration',0x4a54b0:'SelectMovementAnim',0x4a7360:'SelectJumpAnim',0x58dfa0:'NewBlockAction',0x49e2b0:'BlockComboJump',0x62e650:'ResetAnimPacket'}
evidence=[]
for address,name in functions.items():
 instructions=[]
 for i in dis.disasm(n.read(address,0x4000),address):
  if i.mnemonic=='int3':break
  instructions.append({'address':hex(i.address),'bytes':i.bytes.hex(),'mnemonic':i.mnemonic,'operands':i.op_str})
 raw=b''.join(bytes.fromhex(i['bytes'])for i in instructions)
 file=f'decompiled/corpus/FUN_{address:x}.c';text=(BASE/file).read_text()
 evidence.append({'address':hex(address),'name':name,'linearExtentMethod':'Decode until first INT3 padding; static evidence extent, not a control-flow reachability claim.','bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'pseudocode':file,'evidenceId':re.search('ev_[0-9a-f]+',text)[0],'instructions':instructions})
constants=[{'address':hex(a),'format':fmt,'raw':n.read(a,struct.calcsize(fmt)).hex(),'value':n.unpack(fmt,a)[0]}for a,fmt in [(0x751528,'<f'),(0x75bda0,'<d'),(0x7516a8,'<d'),(0x7531c8,'<d'),(0x76b1b8,'<d')]]
source=BASE/'reconstructed/animation/CharacterContexts.cs'
fields=[{'offset':offset,'type':typ,'name':name}for offset,typ,name in re.findall(r'\[FieldOffset\((0x[0-9a-f]+)\)\] public (\w+) (\w+);',source.read_text())]
report={'binarySha256':n.sha256,'functions':evidence,'constants':constants,'partialObjectLayout':{'stride':'0x10d8','strideEvidence':'PC 0x556190 advances object pointer by 0x436 32-bit words. Unnamed bytes are intentionally preserved, not guessed.','fields':fields},'transitionContract':{'procedure':'0x49c080','ready':'action != -1 AND (clip pointer missing OR current packet matches action OR blending target matches action). Source-only match does not qualify.','contexts':{'21':{'name':'TakeHit','readyOperation':'timer=float32(timer-dt); if timer<=0 context=-1'},'90':{'name':'Stunned','readyOperation':'timer=float32(timer-dt); only progress at timer<=0','substates':{'1':'context=-1','other nonzero':'no further mutation','0':'runtimeFlags2 |= 0x8000; dispatch context animation'},'actionDispatch':{'185':'Stop boundary: KillParts(mode=0), then KillGameObject(reason=2).','61':'context=-1','167':'action=170; substate=1; choose new duration','168':'action=171; substate=1; choose new duration','169':'action=172; substate=1; choose new duration','other':'action=1; substate=1; choose new duration'},'duration':'If destination clip exists and definition.flags&2==0, AnimDuration(start=0,end=0,subtractBlendOut=1), otherwise copy object+0x778.'},'95':{'name':'DieAir','readyOperation':'timer=float32(timer+dt)','effectPredicate':'timer>=duration OR (timer>0.5 AND ((priorVerticalVelocity<0 AND groundByte!=0) OR (terrainContact!=0 AND impact > timer/duration * -0.800000011920929 + 0.800000011920929)))','effect':'Stop boundary: optional arcade credit precedes KillParts(mode=1), then KillGameObject(reason=2).'},'96':{'name':'DieGround','behavior':'No branch in this function. Do not infer a 95->96 transition.'}},'effectBoundary':'0x49c1c1, before original call to 0x437770. Fixture uses arcade global 0x93b324=0. No original code or callback is replaced.','postBoundary':'0x4364e0 cleanup then conditional NPC hearts/stud drops; separate root combat investigation, not this portable module.'},'respawnContract':{'resetMoves0':'Original 0x41b420 self-contained common reset tail; no placement, context clear or health restore. Full-image oracle includes random unknown bytes.','resetMoves1':'Not reconstructed here. Requires start-point selection, ResetPlayerMoves, dimensions, prediction, pad rumble, lighting, sockets, level-specific flight placement, headings, current/hover surfaces, gizmos, portals, health/AI/vehicle state.','dependencies':{'0x55e300':'Player_StartPos','0x41af70':'ResetPlayerMoves','0x55d2b0':'position prediction','0x541bc0':'socket association','0x5728a0':'surface probe','0x498480':'hover height','0x466820':'gizmo force reset','0x55d6a0':'portal association','0x414ad0':'AI reset'}},'portableSource':str(source.relative_to(BASE)),'limits':['Reconstructed source is not the original source code.','Field names are evidence-based partial labels; native pointers remain 32-bit identities and are never dereferenced by the C# module.','Finite valid fixtures only. Full game dispatcher, playback advancement, live collision, death media/effects, player respawn placement and scoring integration remain outside coverage.']}
(BASE/'reports/animation-portable-contract.json').write_text(json.dumps(report,indent=2))
print(json.dumps({'functions':len(evidence),'instructions':sum(len(e['instructions'])for e in evidence),'constants':constants,'fields':len(fields)},indent=2))
